const i=$input.first(), r=i.json, keys=Object.keys(i.binary||{});
const clean=(v,n)=>String(v??'').trim().slice(0,n);
const email=clean(r.email,254).toLowerCase(), full_name=clean(r.full_name,120);
const job_id=clean(r.job,100).split('|')[0].trim().toUpperCase();
const email_valid=/^[^\s@<>,;]+@[^\s@<>,;]+\.[^\s@<>,;]+$/.test(email), issues=[];
if(!email_valid) issues.push('Email liên hệ chưa hợp lệ.');
if(full_name.length<2) issues.push('Vui lòng cung cấp họ và tên.');
if(!/^JOB-\d{3}$/.test(job_id)) issues.push('Vị trí ứng tuyển chưa hợp lệ.');
if(!(Array.isArray(r.consent)?r.consent.length:String(r.consent||'').length)) issues.push('Chưa xác nhận việc xử lý hồ sơ.');
let mime='',file_name='',cv;
if(keys.length!==1) issues.push('Vui lòng tải lên đúng một tệp CV.');
else {
 const k=keys[0]; cv=i.binary[k]; file_name=clean(cv.fileName,180);
 const bytes=await this.helpers.getBinaryDataBuffer(0,k);
 const isPdf=bytes.subarray(0,5).toString()==='%PDF-';
 const isPng=bytes.subarray(0,8).toString('hex')==='89504e470d0a1a0a';
 const isJpg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;
 mime=isPdf?'application/pdf':isPng?'image/png':isJpg?'image/jpeg':'';
 if(!mime) issues.push('Tệp CV phải là PDF, JPG hoặc PNG hợp lệ.');
 if(bytes.length>10*1024*1024) issues.push('Dung lượng CV vượt quá 10 MB.');
 if(bytes.length===0) issues.push('Tệp CV không có nội dung.');
 if(mime) cv={...cv,mimeType:mime,fileName:'CV.'+(isPdf?'pdf':isPng?'png':'jpg')};
}
const now=new Date().toISOString();
// Mã hồ sơ (CAN-xxxx) do DB cấp ở bước ghi nhận; trước đó đối chiếu bằng mã lần chạy n8n.
return [{json:{full_name,email,job_id,phone:clean(r.phone,40),cover_letter:clean(r.cover_letter,4000),applied_at:now,consent_at:now,cv_file_name:file_name,cv_mime_type:mime,n8n_execution_id:String($execution.id),valid:issues.length===0,email_valid,issues:issues.join(' '),status:'received'},binary:cv?{cv}:{}}];

