let rest=100-pts.reduce((s,x)=>s+x,0);
raw.map((x,k)=>[x-pts[k],k]).sort((a,b)=>b[0]-a[0]).forEach(([,k])=>{if(rest>0){pts[k]++;rest--;}});
const rubric=skills.map((x,k)=>({id:'R'+(k+1),criterion:x.skill,max_points:pts[k]}));
