const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const c=$('Liên kết CV và soạn thư tiếp nhận').first().json;
let a=null,issue='';
try {
 const texts=[];
 const visit=o=>{if(typeof o==='string'){if(o.trim().startsWith('{'))texts.push(o);}else if(o&&typeof o==='object'){if(typeof o.readable==='boolean'&&typeof o.summary==='string'&&Array.isArray(o.criteria))a=o;for(const[k,v]of Object.entries(o)){if(k==='text'&&typeof v==='string')texts.push(v);else if(typeof v==='object')visit(v);}}};
