const source=fold(text),ok=!!a?.readable&&!issue&&source.length>0;
const rubric=Array.isArray(c.rubric)?c.rubric:[],findings=Array.isArray(a?.criteria)?a.criteria:[];
const notes=[];
// Verify each quotation independently. Ellipses may separate exact excerpts; they never supply evidence.
const hasEvidence=q=>{const chunks=q.split(/\.{3,}|…+/u).map(fold).filter(Boolean);return chunks.length>0&&chunks.every(x=>x.length>=3&&source.includes(x));};
const breakdown=rubric.map(r=>{
 const matches=findings.filter(f=>f.criterion_id===r.id),f=matches[0]||{};
 const validLevel=matches.length===1&&Number.isInteger(f.level)&&[0,1,2].includes(f.level);
 const quote=String(f.evidence_quote||'').trim().slice(0,1000);
 const verified=ok&&validLevel&&(f.level===0||hasEvidence(quote));
 if(!verified)notes.push(r.criterion+': cần HR xác minh; tạm tính 0 cho riêng tiêu chí này.');
 const level=verified?f.level:0;
 return {...r,level,points:r.max_points*level/2,verified,evidence:quote,reason:String(f.reason||'Chưa đủ thông tin.').slice(0,500),question:String(f.question||'').slice(0,500)};
});
const canScore=ok&&rubric.length>0&&breakdown.some(r=>r.verified);
const cv_score=canScore?Math.max(0,Math.min(100,Math.round(breakdown.reduce((s,r)=>s+r.points,0)))):null;
const score_valid=canScore&&breakdown.every(r=>r.verified);
const scoreLine=cv_score===null?'Chưa thể tính điểm — HR vui lòng đọc CV gốc.':'AI tính điểm: '+cv_score+'/100'+(score_valid?'':' (tạm tính; có tiêu chí cần xác minh)')+'.';
const compactSummary=s=>{const t=String(s||'').replace(/\s+/g,' ').trim();if(t.length<=350)return t;const q=t.slice(0,347);const stop=q.lastIndexOf('. ');return stop>=180?q.slice(0,stop+1):q.replace(/\s+\S*$/,'')+'…';};
const summary=ok?compactSummary(a.summary):'Cần HR đọc trực tiếp CV. '+(issue||a?.limitations||'AI không đọc được tệp.');
const interview_questions=[...new Set(breakdown.map(r=>r.question).filter(Boolean))].slice(0,20);
const skills_list=[...new Set((Array.isArray(a?.skills_to_verify)?a.skills_to_verify:[]).map(x=>String(x).trim()).filter(Boolean))].slice(0,20);
const questions=[...new Set([...interview_questions,...skills_list])];
const criteria=breakdown.map(r=>({skill:r.criterion,level:r.level,points:r.points,max_points:r.max_points,verified:r.verified,evidence:r.evidence,reason:r.reason,question:r.question}));
const hours=Number(c.settings?.hr_review_hours)||72;
const ai_summary=summary;
const rows=breakdown.map(r=>'<tr><td style="padding:9px 12px;border-bottom:1px solid #e2e8f0;text-align:left">'+esc(r.criterion)+'</td><td style="padding:9px 12px;border-bottom:1px solid #e2e8f0;white-space:nowrap;text-align:right">'+r.points+'/'+r.max_points+(r.verified?'':' *')+'</td></tr>').join('');
