// Use the signed execution form URL. A suffix prevents this HR link from opening a later candidate form.
const q=reviewUrl.indexOf('?');reviewUrl=q<0?reviewUrl+'/hr-review':reviewUrl.slice(0,q)+'/hr-review'+reviewUrl.slice(q);
const review_html='<html><body style="margin:0;padding:20px;background:#f3f6fa;text-align:left"><table role="presentation" cellpadding="0" cellspacing="0" width="100%"><tr><td align="left"><table role="presentation" cellpadding="0" cellspacing="0" width="760" style="width:100%;max-width:760px;background:#fff;font-family:Arial,sans-serif;font-size:15px;line-height:1.55;color:#243447;text-align:left"><tr><td style="padding:20px 28px;background:#142f4c;color:#fff;font-size:22px;font-weight:bold;text-align:left">ABC Tech <span style="font-size:14px;font-weight:normal">| Phòng Tuyển dụng</span></td></tr><tr><td style="padding:24px 28px;text-align:left"><h2 style="margin:0 0 16px;font-size:21px">Hồ sơ cần HR xem xét</h2><p><b>'+esc(c.full_name)+'</b><br>'+esc(c.job_title)+' · '+esc(c.candidate_id)+'</p><p style="font-size:19px"><b>'+esc(scoreLine)+'</b></p><p>'+esc(summary)+'</p><table cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse;text-align:left"><tr style="background:#eef3f8"><th style="padding:9px 12px;text-align:left">Kỹ năng theo vị trí</th><th style="padding:9px 12px;text-align:right">Điểm</th></tr>'+rows+'</table><p style="font-size:13px;color:#566477">Mỗi kỹ năng: chưa có bằng chứng 0%, chỉ liệt kê 50%, có công việc/dự án cụ thể 100%. '+(score_valid?'':'* Tiêu chí chưa xác minh được tạm tính 0; các tiêu chí khác vẫn được tính.')+'</p><p><a href="'+esc(c.cv_url)+'" style="color:#1761aa">Mở CV gốc trên Google Drive</a></p>'+(questions.length?'<p><b>Gợi ý xác minh khi phỏng vấn</b></p><ul style="padding-left:22px;text-align:left">'+questions.slice(0,3).map(v=>'<li style="margin-bottom:8px">'+esc(v)+'</li>').join('')+'</ul>':'')+'<p>Vui lòng đọc CV và ghi nhận quyết định trong vòng <b>'+hours+' giờ</b>. Điểm AI chỉ hỗ trợ tham khảo; HR quyết định bước tiếp theo.</p><p style="margin:26px 0"><a href="'+esc(reviewUrl)+'" style="display:inline-block;background:#1761aa;color:#fff;text-decoration:none;padding:13px 22px;border-radius:5px;font-weight:bold">Xem xét hồ sơ</a></p><p style="font-size:12px;color:#64748b">Đường dẫn dành riêng cho HR. Vui lòng không chuyển tiếp.</p><p>Trân trọng,<br><b>Bộ phận Tuyển dụng — ABC Tech</b></p></td></tr></table></td></tr></table></body></html>';
