const p=s=>'<p>'+s+'</p>';
const node=n=>{try{return $(n).first().json;}catch(e){return null;}};
const sched=node('Tổng hợp kết quả chọn lịch');
const hr=$('Ghi nhận quyết định HR').first().json;
const saved=node('Lưu quyết định vào DB')||{};
// Nhánh HR không mời phỏng vấn (tạm giữ, chưa phù hợp, quá hạn): trạng thái đã lưu ở "Lưu quyết định vào DB".
// Nếu bước đó không cập nhật được (hồ sơ đã đổi trạng thái ở nơi khác) thì chỉ báo HR.
const c=sched||hr;
const reason=sched?(sched.terminal||'needs_hr_followup'):(Number(saved.updated)>0?hr.status:'state_changed');
const dbStatus={withdrawn:'withdrawn',candidate_response_overdue:'needs_scheduling',reschedule_requested:'needs_scheduling',no_available_slots:'needs_scheduling',scheduling_conflict:'needs_scheduling',needs_hr_followup:'needs_scheduling'}[reason]||'';
const hours=Number(c.hr_review_hours)||72;
const messages={
'on_hold':['Cập nhật hồ sơ ứng tuyển','Bộ phận Tuyển dụng đang tiếp tục xem xét hồ sơ của bạn cho vị trí '+esc(c.job_title)+'. Chúng tôi sẽ liên hệ qua email này khi có thông tin về bước tiếp theo. Bạn có thể trả lời thư nếu muốn bổ sung thông tin hoặc trao đổi về tình trạng hồ sơ.'],
'rejected':['Kết quả xem xét hồ sơ','Cảm ơn bạn đã dành thời gian ứng tuyển vào vị trí '+esc(c.job_title)+' tại ABC Tech. Sau khi xem xét yêu cầu của vị trí và hồ sơ hiện tại, chúng tôi rất tiếc chưa thể mời bạn vào vòng tiếp theo trong đợt tuyển dụng này. Chúng tôi trân trọng sự quan tâm của bạn và chúc bạn sớm tìm được cơ hội phù hợp.'],
'withdrawn':['Xác nhận rút hồ sơ ứng tuyển','ABC Tech đã ghi nhận đề nghị rút hồ sơ của bạn và sẽ dừng việc sắp xếp phỏng vấn cho hồ sơ này. Cảm ơn bạn đã quan tâm đến công ty. Chúc bạn nhiều thuận lợi trong những kế hoạch sắp tới.'],
'candidate_response_overdue':['Cập nhật lời mời phỏng vấn','Chúng tôi chưa nhận được lựa chọn lịch của bạn trong thời gian hiệu lực của lời mời. Chưa có lịch phỏng vấn nào được đặt. Nếu bạn vẫn quan tâm đến vị trí này, vui lòng trả lời email và cho biết thời gian thuận tiện để bộ phận Tuyển dụng hỗ trợ sắp xếp.'],
'reschedule_requested':['Đã nhận đề nghị trao đổi lịch phỏng vấn','ABC Tech đã ghi nhận đề nghị của bạn về thời gian phỏng vấn. Bộ phận Tuyển dụng sẽ trao đổi trực tiếp qua email này để thống nhất lịch phù hợp. Chưa có lịch phỏng vấn nào được xác nhận.'],
'no_available_slots':['Cập nhật việc sắp xếp phỏng vấn','Bộ phận Tuyển dụng đang sắp xếp thêm khung giờ phỏng vấn phù hợp. Chúng tôi sẽ trao đổi trực tiếp qua email này để thống nhất thời gian với bạn. Cảm ơn bạn đã dành thời gian và chờ phản hồi.'],
'scheduling_conflict':['Cập nhật lịch phỏng vấn','Rất tiếc, khung giờ bạn chọn vừa có thay đổi nên chưa thể xác nhận. Bộ phận Tuyển dụng sẽ liên hệ trực tiếp để thống nhất thời gian khác. Chúng tôi xin lỗi vì sự bất tiện này.'],
'state_changed':['HR cần kiểm tra hồ sơ','Hồ sơ đã thay đổi trạng thái hoặc khung giờ không còn đủ thời gian chuẩn bị. HR cần kiểm tra hồ sơ và lịch trước khi liên hệ ứng viên.'],
'hr_overdue':['Hồ sơ cần HR tiếp tục xem xét','Hồ sơ đã quá '+hours+' giờ chờ phản hồi. HR cần đọc CV, liên hệ ứng viên nếu cần và cập nhật trạng thái. Không tự động từ chối ứng viên.']
};
const labels={on_hold:'Tạm giữ',rejected:'Không phù hợp',hr_overdue:'Quá hạn duyệt',withdrawn:'Ứng viên rút hồ sơ',candidate_response_overdue:'Ứng viên chưa chọn giờ',reschedule_requested:'Ứng viên xin đổi giờ',no_available_slots:'Hết khung giờ trống',scheduling_conflict:'Khung giờ vừa bị trùng',state_changed:'Hồ sơ đã đổi trạng thái',needs_hr_followup:'Cần HR theo dõi'};
const [title,body]=messages[reason]||['Cập nhật hồ sơ','Bộ phận Tuyển dụng sẽ trao đổi trực tiếp với bạn về bước tiếp theo.'];
const label=labels[reason]||reason;
const note=c.candidate_note?'[Ứng viên] '+c.candidate_note:'';
return [{json:{...c,reason,status:dbStatus||reason,update_status:!!dbStatus,actor:['withdrawn','reschedule_requested'].includes(reason)?'candidate':'system',note,send_candidate:!['hr_overdue','state_changed'].includes(reason),mail_subject:'[ABC Tech] '+title+' | '+c.candidate_id,
mail_html:wrap(title,p('Chào bạn '+esc(c.full_name)+',')+p(body)+p('Mã hồ sơ: '+esc(c.candidate_id)+'.')),
hr_html:wrap('Cập nhật hồ sơ — cần theo dõi',p('Hồ sơ: '+esc(c.candidate_id)+' — '+esc(c.full_name)+'<br>Email: '+esc(c.email)+'<br>Tình trạng: <b>'+esc(label)+'</b>')+p('Ghi chú: '+esc([c.hr_note,note].filter(Boolean).join(' | ')||'Không có.'))+p('Với hồ sơ tạm giữ, quá hạn hoặc cần xếp lịch lại: HR chủ động liên hệ ứng viên và cập nhật trạng thái hồ sơ sau khi xử lý.')+(c.cv_url?p('<a href="'+esc(c.cv_url)+'">Mở CV gốc</a>'):'')),
log_message:'Kết thúc nhánh tự động: '+label,log_level:['hr_overdue','state_changed','scheduling_conflict'].includes(reason)?'warning':'info'}}];

const c=$('Soạn kết quả và chỉ định người nhận').first().json;
const hrEmail=c.hr_email||'whateverholding246@gmail.com';
const list=[];
if(c.send_candidate&&/^[^\s@<>,;]+@[^\s@<>,;]+\.[^\s@<>,;]+$/.test(c.email||''))list.push({json:{...c,mail_recipient:c.email,mail_subject:c.mail_subject,mail_html:c.mail_html,log_message:'Đã gửi cập nhật hồ sơ cho ứng viên: '+c.reason},pairedItem:{item:0}});
list.push({json:{...c,mail_recipient:hrEmail,mail_subject:'[ABC Tech | HR] '+c.reason+' — '+c.candidate_id,mail_html:c.hr_html,log_message:'Đã gửi kết quả cần theo dõi cho HR: '+c.reason},pairedItem:{item:0}});
return list;

